import{_ as a,o as e,c as p,am as n}from"./chunks/framework._FJXuPhs.js";const u=JSON.parse('{"title":"Docker Compose","description":"","frontmatter":{"title":"Docker Compose","excerpt":"Docker Compose基础使用","date":"2024-03-21 22:53:07","updated":"2024-03-21 22:53:07"},"headers":[],"relativePath":"部署&工具/Java 知识体系-容器部署/Docker Compose/index.md","filePath":"部署&工具/Java 知识体系-容器部署/Docker Compose/index.md","lastUpdated":null}'),o={name:"部署&工具/Java 知识体系-容器部署/Docker Compose/index.md"};function c(i,s,t,l,r,d){return e(),p("div",null,[...s[0]||(s[0]=[n(`<h2 id="docker-compose安装" tabindex="-1">Docker-compose安装 <a class="header-anchor" href="#docker-compose安装" aria-label="Permalink to &quot;Docker-compose安装&quot;">​</a></h2><ul><li><a href="/java-site/部署%26工具/Java 知识体系-容器部署/Docker Compose/Docker-compose安装.html">Docker-compose安装</a></li></ul><h2 id="docker-compose-的基础使用" tabindex="-1">Docker Compose 的基础使用 <a class="header-anchor" href="#docker-compose-的基础使用" aria-label="Permalink to &quot;Docker Compose 的基础使用&quot;">​</a></h2><p>介绍：<code>Compose</code> 项目是 Docker 官方的开源项目，负责实现对 Docker 容器集群的快速编排。</p><p>Compose 允许用户通过一个单独的 <code>docker-compose.yml</code> 模板文件（YAML 格式）来定义一组相关联的应用容器为一个项目（project）</p><p><code>Compose</code> 中有两个重要的概念：</p><ul><li>服务 (<code>service</code>)：一个应用的容器，实际上可以包括若干运行相同镜像的容器实例。</li><li>项目 (<code>project</code>)：由一组关联的应用容器组成的一个完整业务单元，在 <code>docker-compose.yml</code> 文件中定义。</li></ul><h3 id="_1、安装与卸载" tabindex="-1">1、安装与卸载 <a class="header-anchor" href="#_1、安装与卸载" aria-label="Permalink to &quot;1、安装与卸载&quot;">​</a></h3><p>Linux</p><p><a href="/java-site/部署%26工具/Java 知识体系-容器部署/Docker Compose/Docker-compose安装.html">Docker-compose安装</a></p><p>docker compose 是一个工具，能够实现快速编排。</p><p>windows/macOS</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240321230040.png" alt="image.png"></p><p>卸载操作：</p><p>如果是 windows 或者 macOS ，需要卸载一下 Docker Desktop。</p><p>如果 Docker Compose 是作为一个单独的二进制文件安装的：</p><ol><li><p><strong>找到 Docker Compose 的安装位置</strong>。如果你不确定其安装位置，可以通过运行 <code>which docker-compose</code>（在 Linux 或 Mac 上）或 <code>where docker-compose</code>（在 Windows 上）来找到它。</p></li><li><p><strong>删除 Docker Compose 二进制文件</strong>。一旦你知道了 Docker Compose 的安装位置，你可以手动删除该文件。在 Linux 或 Mac 上，通常可以使用 <code>sudo rm</code> 命令来删除：</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo rm \`which docker-compose\`</span></span></code></pre></div><hr><h3 id="_2、如何使用" tabindex="-1">2、如何使用 <a class="header-anchor" href="#_2、如何使用" aria-label="Permalink to &quot;2、如何使用&quot;">​</a></h3><p>Compose 使用的三个步骤：</p><ul><li>使用 Dockerfile 定义应用程序的环境。</li><li>使用 docker-compose.yml 定义构成应用程序的服务，这样它们可以在隔离环境中一起运行。</li><li>最后，执行 docker-compose up 命令来启动并运行整个应用程序。</li></ul><p>示例使用：</p><p>准备一个 SpringBoot 的项目，并打包为 Jar 包</p><p>放置到 Linux 的一个文件夹下</p><p>创建文件：Dockerfile</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 使用官方 Java 运行时环境作为基础镜像</span></span>
<span class="line"><span>FROM openjdk:8</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 工作目录设为 /app</span></span>
<span class="line"><span>WORKDIR /app</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 将本地的 JAR 文件复制到镜像中的 /app 目录</span></span>
<span class="line"><span>COPY ./zfile-4.1.5.jar /app/myapp_zfile.jar</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 暴露应用运行端口</span></span>
<span class="line"><span>EXPOSE 8091</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 指定容器启动时执行的命令</span></span>
<span class="line"><span>CMD [&quot;java&quot;, &quot;-jar&quot;, &quot;myapp_zfile.jar&quot;]</span></span></code></pre></div><p>创建文件 docker-compose.yml</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>version: &#39;3.8&#39;</span></span>
<span class="line"><span>services:</span></span>
<span class="line"><span>  app:</span></span>
<span class="line"><span>    build: .</span></span>
<span class="line"><span>    container_name: myapp_zfile</span></span>
<span class="line"><span>    ports:</span></span>
<span class="line"><span>      - &quot;8091:8091&quot;</span></span></code></pre></div><p>使用 Docker Compose 启动应用</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker-compose up --build</span></span></code></pre></div><p>有一个报错：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>failed to solve: openjdk:8-jre-slim: failed to do request: Head &quot;https://7iwp6tq0.mirror.aliyuncs.com/v2/library/openjdk/manifests/8-jre-slim?ns=docker.io&quot;: dial tcp: lookup 7iwp6tq0.mirror.aliyuncs.com on 192.168.0.1:53: read udp 192.168.0.21:53861-&gt;192.168.0.1:53: read: connection refused</span></span></code></pre></div><p>最后定位到是 DNS 配置的原因</p><p>先尝试改了 Docker 镜像源的配置 配置文件 /etc/docker/daemon.json</p><p>改为了</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;registry-mirrors&quot;: [&quot;https://hub-mirror.c.163.com&quot;]</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>还是报错，尝试访问 <code>ping hub-mirror.c.163.com</code>; 网络是正常的</p><p>尝试修改 DNS 配置文件 /etc/resolv.conf；改为了阿里云公共 DNS，</p><p>参考链接： <a href="https://zhuanlan.zhihu.com/p/339495904" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/339495904</a></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Generated by NetworkManager</span></span>
<span class="line"><span>nameserver 223.6.6.6</span></span></code></pre></div><p>启动正常</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#后台执行</span></span>
<span class="line"><span>docker-compose up -d</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#停止服务</span></span>
<span class="line"><span>docker-compose down</span></span></code></pre></div><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240322085150.png" alt="image.png"></p><p>其他的使用参考一下这个： <a href="https://juejin.cn/post/7042663735156015140" target="_blank" rel="noreferrer">https://juejin.cn/post/7042663735156015140</a></p><h3 id="快速使用" tabindex="-1">快速使用 <a class="header-anchor" href="#快速使用" aria-label="Permalink to &quot;快速使用&quot;">​</a></h3><p>安装 docker compose</p><p>指定文件后，选择后台运行</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker-compose -f docker-compose-environment-aliyun.yml up -d</span></span></code></pre></div><hr><p>参考</p><ul><li><a href="https://yeasy.gitbook.io/docker_practice/compose/introduction" target="_blank" rel="noreferrer">https://yeasy.gitbook.io/docker_practice/compose/introduction</a></li></ul>`,52)])])}const m=a(o,[["render",c]]);export{u as __pageData,m as default};
